#!/bin/sh
# Start-up for the local demo started by `docker compose up`.
#
# It writes demo-only configuration INSIDE the container (never into the
# project), applies the migrations to the demo database, loads demo data
# once, then starts Apache. The real shop never uses this file.
set -eu

app=/var/www/html
config="$app/app/config"

# Demo database settings come from docker-compose.yml.
if [ ! -f "$config/database.local.php" ]; then
    cat > "$config/database.local.php" <<PHP
<?php
// Generated by docker/demo/entrypoint.sh for the local demo only.
return [
    'host' => '${DEMO_DB_HOST}',
    'port' => 5432,
    'database' => '${DEMO_DB_NAME}',
    'username' => '${DEMO_DB_USER}',
    'password' => '${DEMO_DB_PASSWORD}',
];
PHP
fi

# A random key for the login rate limiter, created once per container.
if [ ! -f "$config/login-throttle.local.php" ]; then
    key=$(php -r 'echo bin2hex(random_bytes(32));')
    printf "<?php\nreturn ['key' => '%s'];\n" "$key" > "$config/login-throttle.local.php"
fi
chown www-data:www-data "$config/database.local.php" "$config/login-throttle.local.php"
chmod 640 "$config/database.local.php" "$config/login-throttle.local.php"

echo "Waiting for the demo database..."
tries=0
until php -r 'require "/var/www/html/app/config/database.php"; database()->query("SELECT 1");' >/dev/null 2>&1; do
    tries=$((tries + 1))
    if [ "$tries" -ge 60 ]; then
        echo "The demo database did not become reachable." >&2
        exit 1
    fi
    sleep 1
done

php "$app/scripts/migrate.php" >/dev/null
echo "Migrations applied."
php "$app/docker/demo/seed-demo.php"

exec apache2-foreground
